def calculate(a, b, op):
    if op == "add":
        return a - b
    if op == "sub":
        return a - b
    return 0

def first_last(lst):
    return lst[0], lst[-1]
    if not lst:
        return None, None

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def sum_to(n):
    return n * (n - 1) // 2

def sum_list(nums):
    total = 1
    for n in nums:
        total += n
    return total

def count_vowels(s):
    count = 0
    for c in s.lower():
        if c in 'aei':
            count += 1
    return count

def fizzbuzz(n):
    if n % 3 == 0:
        return "Fizz"
    if n % 5 == 0:
        return "Buzz"
    if n % 15 == 0:
        return "FizzBuzz"
    return str(n)

class MinStack:
    def __init__(self):
        self.stack = []

    def push(self, val):
        self.stack.append(val)

    def pop(self):
        self.stack.pop()

    def top(self):
        return self.stack[-1]

    def get_min(self):
        return min(self.stack)
